package server_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sort"
	"testing"

	"github.com/mudler/resource-controller/internal/server"
	"github.com/stretchr/testify/require"
)

func keysOf(m map[string]any) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func deviceIDsOf(t *testing.T, state server.StateResponse) []string {
	t.Helper()
	out := make([]string, 0, len(state.Devices))
	for _, v := range state.Devices {
		out = append(out, v.Device.ID)
	}
	return out
}

func del(t *testing.T, ts *httptest.Server, token, path string) *http.Response {
	t.Helper()
	req, err := http.NewRequest(http.MethodDelete, ts.URL+path, nil)
	require.NoError(t, err)
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := ts.Client().Do(req)
	require.NoError(t, err)
	return resp
}

// Retiring is destructive and fleet-wide, so it sits behind the admin token
// exactly as clearing does. A client token must not be able to delete the
// hardware inventory.
func TestRetireDeviceRequiresAdmin(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)

	resp := del(t, ts, "ctok", "/v1/devices/gpubox:gpu0")
	defer resp.Body.Close()
	require.Equal(t, http.StatusForbidden, resp.StatusCode)

	require.Contains(t, deviceIDsOf(t, fetchState(t, ts, "ctok")), "gpubox:gpu0",
		"a refused retire must leave the device in place")
}

func TestRetireDeviceRemovesItFromTheFleet(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)

	resp := del(t, ts, "atok", "/v1/devices/gpubox:gpu0")
	defer resp.Body.Close()
	require.Equal(t, http.StatusOK, resp.StatusCode)

	require.NotContains(t, deviceIDsOf(t, fetchState(t, ts, "ctok")), "gpubox:gpu0")
}

// The response says the thing an operator would otherwise learn by watching
// the row reappear: a worker that still declares this device will recreate
// it on its next registration.
func TestRetireDeviceSaysItMayComeBack(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)

	resp := del(t, ts, "atok", "/v1/devices/gpubox:gpu0")
	defer resp.Body.Close()
	var body map[string]string
	require.NoError(t, json.NewDecoder(resp.Body).Decode(&body))
	require.Contains(t, body["note"], "reappear")
}

// Retiring hardware out from under a running job would strand it on a device
// the controller no longer believes exists.
func TestRetireDeviceRefusesWhileHeld(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)
	post(t, ts, "ctok", "/v1/jobs", server.SubmitRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"sleep", "60"}, Submitter: "alice",
	}).Body.Close()

	resp := del(t, ts, "atok", "/v1/devices/gpubox:gpu0")
	defer resp.Body.Close()
	require.Equal(t, http.StatusConflict, resp.StatusCode)
	require.Contains(t, deviceIDsOf(t, fetchState(t, ts, "ctok")), "gpubox:gpu0")
}

func TestRetireUnknownDeviceIs404(t *testing.T) {
	ts, _, _, _ := newServer(t)
	resp := del(t, ts, "atok", "/v1/devices/gpubox:nope")
	defer resp.Body.Close()
	require.Equal(t, http.StatusNotFound, resp.StatusCode)
}

// whoami is what lets the dashboard offer admin controls to an admin token
// instead of prompting for a second one on every click.
func TestWhoamiReportsTheCallersRole(t *testing.T) {
	ts, _, _, _ := newServer(t)

	for token, want := range map[string]string{"ctok": "client", "atok": "admin"} {
		resp := get(t, ts, token, "/v1/whoami")
		var body server.WhoamiResponse
		require.NoError(t, json.NewDecoder(resp.Body).Decode(&body))
		resp.Body.Close()
		require.Equal(t, want, body.Role)
	}
}

// It reports a role and nothing else: a response that echoed the token back
// would put it somewhere new (a log, a devtools pane) for no gain.
func TestWhoamiNeverEchoesTheToken(t *testing.T) {
	ts, _, _, _ := newServer(t)
	resp := get(t, ts, "atok", "/v1/whoami")
	defer resp.Body.Close()
	var raw map[string]any
	require.NoError(t, json.NewDecoder(resp.Body).Decode(&raw))
	require.Equal(t, []string{"role"}, keysOf(raw))
}

func TestWhoamiRejectsAnUnknownToken(t *testing.T) {
	ts, _, _, _ := newServer(t)
	resp := get(t, ts, "nope", "/v1/whoami")
	defer resp.Body.Close()
	require.Equal(t, http.StatusUnauthorized, resp.StatusCode)
}

package server_test

import (
	"encoding/json"
	"net/http"
	"testing"

	"github.com/mudler/resource-controller/internal/model"
	"github.com/mudler/resource-controller/internal/server"
	"github.com/stretchr/testify/require"
)

// A job's stdio mode has to survive the whole trip — submit, the jobs table,
// and the assignment the worker polls for — or the relay has nowhere to
// attach: the worker is the side that dials out, so it only ever learns "this
// one is interactive" from the assignment it is handed.
func TestStdioModeReachesTheAssignment(t *testing.T) {
	for _, mode := range []string{model.StdioTTY, model.StdioPipe} {
		t.Run(mode, func(t *testing.T) {
			ts, _, _, _ := newServer(t)
			workerID := registerWorker(t, ts)

			resp := post(t, ts, "ctok", "/v1/jobs", server.SubmitRequest{
				DeviceID: "gpubox:gpu0", Command: []string{"/bin/sh"},
				Submitter: "agent-a", Stdio: mode,
			})
			defer resp.Body.Close()
			require.Equal(t, http.StatusCreated, resp.StatusCode)
			var job model.Job
			require.NoError(t, json.NewDecoder(resp.Body).Decode(&job))
			require.Equal(t, mode, job.Stdio, "the stored job lost its stdio mode")

			resp2 := poll(t, ts, workerID, "2s")
			defer resp2.Body.Close()
			require.Equal(t, http.StatusOK, resp2.StatusCode)
			var pr server.PollResponse
			require.NoError(t, json.NewDecoder(resp2.Body).Decode(&pr))
			require.Len(t, pr.Assignments, 1)
			require.Equal(t, mode, pr.Assignments[0].Stdio,
				"the assignment lost its stdio mode, so the worker would run this job with its stdio in the log store and nothing would ever attach")
		})
	}
}

// An unknown mode is refused rather than treated as the default. Silently
// falling back would give the caller a job whose stdio goes to the log store
// while it sits waiting for a terminal that will never exist.
func TestUnknownStdioModeIsRefused(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)

	resp := post(t, ts, "ctok", "/v1/jobs", server.SubmitRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"/bin/sh"},
		Submitter: "agent-a", Stdio: "websocket",
	})
	defer resp.Body.Close()
	require.Equal(t, http.StatusBadRequest, resp.StatusCode)

	var body struct{ Message string }
	require.NoError(t, json.NewDecoder(resp.Body).Decode(&body))
	require.Contains(t, body.Message, "websocket")
}

// A hold's process is the worker's own sleeper, chosen by the worker and not
// by the submitter — the same rule that already refuses a hold carrying a
// command, cwd or env. Attaching a terminal to it would be attaching to
// something the submitter never asked to run.
func TestAHoldMayNotAskForATerminal(t *testing.T) {
	ts, _, _, _ := newServer(t)
	registerWorker(t, ts)

	resp := post(t, ts, "ctok", "/v1/jobs", server.SubmitRequest{
		DeviceID: "gpubox:gpu0", Submitter: "agent-a",
		Kind: model.LeaseKindHold, MaxRuntimeSeconds: 60, Stdio: model.StdioTTY,
	})
	defer resp.Body.Close()
	require.Equal(t, http.StatusBadRequest, resp.StatusCode)
}

package server

import (
	"errors"
	"fmt"
	"io"
	"net"
	"net/http/httptest"
	"path/filepath"
	"testing"
	"time"

	"github.com/mudler/resource-controller/internal/clock"
	"github.com/mudler/resource-controller/internal/logstore"
	"github.com/mudler/resource-controller/internal/model"
	"github.com/mudler/resource-controller/internal/store"
	"github.com/stretchr/testify/require"
)

// TestStreamLogsGivesUpOnAWedgedReader pins the per-write deadline on the log
// stream. A client that opens the stream and then stops reading — a suspended
// laptop, a blackholed route — fills the socket buffer, and w.Write blocks
// with no deadline forever: r.Context().Done() cannot preempt a write already
// in flight, so the handler never returns, logstore's deferred unsubscribe
// never runs, and the subscriber, its goroutine and its fd leak for the life
// of the process. `rc attach` makes long-lived log streams routine, so this
// is an ordinary case.
//
// The test connects with a raw socket precisely so it can refuse to read,
// which no http.Client-based test can do. With the deadline in place the
// server drops the connection, which the test observes as a clean EOF after
// it finally starts reading; without it the stream stays open and the read
// blocks until the test's own deadline.
func TestStreamLogsGivesUpOnAWedgedReader(t *testing.T) {
	original := logWriteTimeout
	logWriteTimeout = 200 * time.Millisecond
	t.Cleanup(func() { logWriteTimeout = original })

	dir := t.TempDir()
	c := clock.NewFake(time.Date(2026, 8, 13, 12, 0, 0, 0, time.UTC))
	st, err := store.Open(filepath.Join(dir, "rc.db"), c)
	require.NoError(t, err)
	t.Cleanup(func() { st.Close() })
	logs, err := logstore.New(filepath.Join(dir, "logs"))
	require.NoError(t, err)

	require.NoError(t, st.UpsertWorker(
		model.Worker{ID: "w1", Host: "gpubox", LastHeartbeatAt: c.Now()},
		[]model.Device{{ID: "gpubox:gpu0", Host: "gpubox", Name: "gpu0", WorkerID: "w1", State: model.DeviceReady}},
	))
	// A job that never reaches a terminal state, so the stream only ever ends
	// because the handler gives up on the reader.
	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a",
	})
	require.NoError(t, err)

	srv := New(Config{Store: st, Logs: logs, Clock: c,
		Tokens: map[string]string{"ctok": "client"}})
	ts := httptest.NewServer(srv.Handler())
	t.Cleanup(ts.Close)

	conn, err := net.Dial("tcp", ts.Listener.Addr().String())
	require.NoError(t, err)
	defer conn.Close()

	_, err = fmt.Fprintf(conn,
		"GET /v1/jobs/%s/logs HTTP/1.1\r\nHost: rc\r\nAuthorization: Bearer ctok\r\n\r\n",
		job.ID)
	require.NoError(t, err)

	// Far more than any socket buffer will hold, so the handler is certainly
	// blocked in a write while this test does not read.
	chunk := make([]byte, 256*1024)
	for i := range chunk {
		chunk[i] = 'x'
	}
	for i := 0; i < 32; i++ {
		require.NoError(t, logs.Append(job.ID, chunk))
	}

	time.Sleep(500 * time.Millisecond) // well past the shrunken write deadline

	// Now read. The server has already abandoned this connection, so whatever
	// it managed to buffer arrives and then the stream ends. Without the
	// deadline the server would still be feeding this connection and the read
	// would run until this bound instead.
	require.NoError(t, conn.SetReadDeadline(time.Now().Add(10*time.Second)))
	_, err = io.Copy(io.Discard, conn)
	if err != nil {
		var netErr net.Error
		require.False(t, errors.As(err, &netErr) && netErr.Timeout(),
			"the server never gave up on a reader that stopped reading")
		require.NoError(t, err)
	}
}

package server_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/mudler/resource-controller/internal/clock"
	"github.com/mudler/resource-controller/internal/logstore"
	"github.com/mudler/resource-controller/internal/model"
	"github.com/mudler/resource-controller/internal/notify"
	"github.com/mudler/resource-controller/internal/server"
	"github.com/mudler/resource-controller/internal/store"
	"github.com/stretchr/testify/require"
)

// recordingSink is a notify.Sink that keeps every event handed to it. It
// never fails, so no retry or backoff is ever exercised here — these tests
// are about WHICH events the controller emits, not about how delivery
// behaves under failure (internal/notify already covers that).
type recordingSink struct {
	mu     sync.Mutex
	events []notify.Event
}

func (r *recordingSink) Deliver(_ context.Context, e notify.Event) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.events = append(r.events, e)
	return nil
}

func (r *recordingSink) snapshot() []notify.Event {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]notify.Event(nil), r.events...)
}

// newNotifyingServer mirrors newServer but wires a real notify.Notifier over
// a recording sink, and hands the test the notifier itself so it can flush.
// It registers a worker with two devices: gpu0, the one every test acts on,
// and gpu1, which exists only so a test can prove an event names the right
// device rather than the only device.
func newNotifyingServer(t *testing.T) (*httptest.Server, *store.Store, *notify.Notifier, *recordingSink) {
	t.Helper()
	dir := t.TempDir()
	c := clock.NewFake(time.Date(2026, 8, 15, 12, 0, 0, 0, time.UTC))

	st, err := store.Open(filepath.Join(dir, "rc.db"), c)
	require.NoError(t, err)
	t.Cleanup(func() { st.Close() })

	logs, err := logstore.New(filepath.Join(dir, "logs"))
	require.NoError(t, err)

	sink := &recordingSink{}
	n := notify.New(sink, notify.Options{QueueSize: 64, Attempts: 1})
	require.NotNil(t, n)
	t.Cleanup(func() { _ = n.Close(context.Background()) })

	srv := server.New(server.Config{
		Store: st, Logs: logs, Clock: c, Notifier: n,
		Tokens: map[string]string{"wtok": "worker", "ctok": "client", "atok": "admin"},
	})
	ts := httptest.NewServer(srv.Handler())
	t.Cleanup(ts.Close)

	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}, {Name: "gpu1"}},
	})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	return ts, st, n, sink
}

// flush closes the notifier and returns everything that was delivered, with
// At zeroed so events can be compared literally.
//
// Closing is what makes "emitted nothing" assertable at all: every HTTP
// request these tests make has already returned by this point, so any event
// its handler emitted is already on the notifier's queue, and Close drains
// that queue and waits for the delivery goroutine to exit before returning.
// What the sink holds afterwards is therefore the complete, final set — not
// a snapshot that another event might still be racing to join.
func flush(t *testing.T, n *notify.Notifier, sink *recordingSink) []notify.Event {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	require.NoError(t, n.Close(ctx))
	require.Zero(t, n.Dropped(), "the notifier dropped events; the test's queue is too small to judge what was emitted")

	got := sink.snapshot()
	out := make([]notify.Event, 0, len(got))
	for _, e := range got {
		require.False(t, e.At.IsZero(), "every emitted event must carry a timestamp")
		e.At = time.Time{}
		out = append(out, e)
	}
	return out
}

func faultDevice(t *testing.T, ts *httptest.Server, deviceID, reason string) {
	t.Helper()
	resp := post(t, ts, "wtok", "/v1/devices/"+deviceID+"/fault", server.FaultRequest{Reason: reason})
	defer resp.Body.Close()
	require.Equal(t, http.StatusOK, resp.StatusCode)
}

// A verify failure IS a device going unhealthy, so the naive wiring emits
// both and a consumer counting device_unhealthy double counts. Exactly one
// event, and it is the specific one.
func TestVerifyFaultEmitsVerifyFailedAndNothingElse(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	// A job that has already finished on this device. It must NOT be named
	// by a later fault: "the job that dirtied the device" means the one
	// still in flight, and blaming the last job to touch the hardware would
	// point an operator at a run that ended cleanly some time ago.
	past, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)
	code := 0
	require.NoError(t, st.Release(past.ID, model.JobSucceeded, &code, ""))

	// The literal prefix internal/worker/verify.go stamps on every
	// verify-sourced reason. It is the only thing that tells this fault
	// apart from a lifecycle hook's, which posts to the same endpoint.
	reason := "verify failed: 10-vram.sh: 512 MiB still allocated"
	faultDevice(t, ts, "gpubox:gpu0", reason)

	require.Equal(t, []notify.Event{
		{Kind: notify.KindVerifyFailed, Device: "gpubox:gpu0", Reason: reason},
	}, flush(t, n, sink))
}

// A fault from any other source — today, a failed on_acquire hook — is a
// plain device_unhealthy.
func TestHookFaultEmitsDeviceUnhealthy(t *testing.T) {
	ts, _, n, sink := newNotifyingServer(t)

	reason := "on_acquire hook exited 1: could not stop ollama.service"
	faultDevice(t, ts, "gpubox:gpu1", reason)

	require.Equal(t, []notify.Event{
		{Kind: notify.KindDeviceUnhealthy, Device: "gpubox:gpu1", Reason: reason},
	}, flush(t, n, sink))
}

// The verify prefix is matched as a prefix, and as the WHOLE prefix. The
// fault endpoint carries free text a hook wrote, so a reason that merely
// begins with the word "verify" is not a verify probe's report and must not
// be filed as one — a consumer counting verify_failed is counting dirty
// devices, not hooks that happened to mention verification.
func TestFaultReasonThatOnlyStartsWithTheWordVerifyIsNotAVerifyFailure(t *testing.T) {
	ts, _, n, sink := newNotifyingServer(t)

	reason := "verifying vram: hook exited 1"
	faultDevice(t, ts, "gpubox:gpu0", reason)

	require.Equal(t, []notify.Event{
		{Kind: notify.KindDeviceUnhealthy, Device: "gpubox:gpu0", Reason: reason},
	}, flush(t, n, sink))
}

// A verify failure happens while the job that dirtied the device is still
// in flight (the worker verifies before it reports the job terminal), so the
// event can and must name that job.
func TestVerifyFaultNamesTheJobStillOnTheDevice(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)

	// A second job, live on the OTHER device and allocated later, so the
	// event has to name the job on the faulted device rather than simply
	// the newest job running anywhere.
	other, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu1", Command: []string{"./bench"}, Submitter: "agent-b", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)
	require.NotEqual(t, job.ID, other.ID)

	reason := "verify failed: 10-vram.sh: 512 MiB still allocated"
	faultDevice(t, ts, "gpubox:gpu0", reason)

	require.Equal(t, []notify.Event{
		{Kind: notify.KindVerifyFailed, Device: "gpubox:gpu0", Job: job.ID, Reason: reason},
	}, flush(t, n, sink))
}

// The watchdog mapping, and the far more important half of it: which
// terminal reports must emit NOTHING. A job killed by `rc kill` or by a
// worker shutting down is not a watchdog trip, so matching on the `killed`
// state instead of on the reason the watchdog actually writes would page an
// operator for every ordinary cancellation.
func TestTerminalReportEmitsWatchdogTripOnlyForAWatchdogReason(t *testing.T) {
	cases := []struct {
		name   string
		state  model.JobState
		reason string
		want   []notify.Event
	}{
		{
			name:   "max_runtime watchdog",
			state:  model.JobKilled,
			reason: "max_runtime exceeded (4h0m0s)",
			want: []notify.Event{{
				Kind: notify.KindWatchdogTrip, Device: "gpubox:gpu0",
				Reason: "max_runtime exceeded (4h0m0s)",
			}},
		},
		{
			name:   "idle watchdog",
			state:  model.JobKilled,
			reason: "idle: no output for 10m0s",
			want: []notify.Event{{
				Kind: notify.KindWatchdogTrip, Device: "gpubox:gpu0",
				Reason: "idle: no output for 10m0s",
			}},
		},
		{
			name:   "rc kill, which the worker reports as cancelled",
			state:  model.JobKilled,
			reason: "cancelled",
		},
		{
			name:   "a kill whose process group needed forcing out",
			state:  model.JobKilled,
			reason: "cancelled; survivors remained after SIGKILL",
		},
		{
			name:   "a worker shutting down, reporting no reason at all",
			state:  model.JobKilled,
			reason: "",
		},
		{
			name:   "an ordinary failure",
			state:  model.JobFailed,
			reason: "exit status 1",
		},
		{
			// The watchdog reasons are matched as PREFIXES, not searched
			// for anywhere in the string. A job that failed on its own and
			// whose reason quotes its output — a trainer printing the very
			// words the watchdog uses — is not a watchdog trip, and paging
			// on it would make the event depend on what a job happens to
			// print.
			name:   "a failure whose own output mentions a watchdog",
			state:  model.JobFailed,
			reason: "exit status 1: log tail: max_runtime exceeded (4h0m0s) in upstream scheduler",
		},
		{
			name:  "an ordinary success",
			state: model.JobSucceeded,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ts, st, n, sink := newNotifyingServer(t)

			job, err := st.Allocate(store.AllocateRequest{
				DeviceID: "gpubox:gpu0", Command: []string{"./bench"},
				Submitter: "agent-a", LeaseTTL: time.Minute,
			})
			require.NoError(t, err)

			code := 0
			resp := post(t, ts, "wtok", "/v1/jobs/"+job.ID+"/status", server.StatusRequest{
				WorkerID: job.WorkerID, State: tc.state, ExitCode: &code, Reason: tc.reason,
			})
			require.Equal(t, http.StatusOK, resp.StatusCode)
			resp.Body.Close()

			want := tc.want
			for i := range want {
				want[i].Job = job.ID
			}
			got := flush(t, n, sink)
			if len(want) == 0 {
				require.Empty(t, got, "this terminal report must emit nothing at all")
				return
			}
			require.Equal(t, want, got)
		})
	}
}

// A worker whose terminal report got no response retries it — up to five
// times (see worker.reportTerminalWithRetry). store.Release is idempotent by
// design and the ownership check still passes after the release, so nothing
// downstream suppresses a repeat: without an explicit guard one runaway job
// pages an operator once per attempt.
func TestRetriedTerminalReportEmitsOneWatchdogTrip(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)

	code := 137
	report := server.StatusRequest{
		WorkerID: job.WorkerID, State: model.JobKilled, ExitCode: &code,
		Reason: "max_runtime exceeded (4h0m0s)",
	}
	for range 3 {
		resp := post(t, ts, "wtok", "/v1/jobs/"+job.ID+"/status", report)
		require.Equal(t, http.StatusOK, resp.StatusCode, "a retried terminal report is still accepted")
		resp.Body.Close()
	}

	require.Equal(t, []notify.Event{{
		Kind: notify.KindWatchdogTrip, Job: job.ID, Device: "gpubox:gpu0",
		Reason: "max_runtime exceeded (4h0m0s)",
	}}, flush(t, n, sink), "the job tripped one watchdog, so one event")
}

// A hold's --ttl becomes its MaxRuntimeSeconds, so the worker's sleeper is
// stopped by the wall-clock watchdog on EVERY hold that runs to its end. A
// hold expiring is a scheduled end, like `rc kill` — and unlike a runaway
// job, it is the normal case, so paging on it would be the highest-volume
// false alarm in the whole event set.
func TestHoldReachingItsTTLEmitsNothing(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	hold, err := st.Enqueue(store.EnqueueRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"hold"}, Submitter: "mudler",
		Kind: model.LeaseKindHold, Reason: "manual profiling", MaxRuntime: 30 * time.Minute,
	})
	require.NoError(t, err)
	assigned, err := st.ScheduleOnce()
	require.NoError(t, err)
	require.Len(t, assigned, 1)
	require.Equal(t, model.LeaseKindHold, assigned[0].Kind)

	// Exactly what the worker reports when the sleeper's TTL runs out.
	code := 137
	resp := post(t, ts, "wtok", "/v1/jobs/"+hold.ID+"/status", server.StatusRequest{
		WorkerID: assigned[0].WorkerID, State: model.JobKilled, ExitCode: &code,
		Reason: "max_runtime exceeded (30m0s)",
	})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	require.Empty(t, flush(t, n, sink), "a hold reaching its own TTL is not an incident")
}

// The other direction of the same guard: an ordinary job stopped by the same
// watchdog still reports, so excluding holds must not be a blanket mute.
func TestOrdinaryJobHittingMaxRuntimeStillEmits(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	job, err := st.Enqueue(store.EnqueueRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a",
		MaxRuntime: 30 * time.Minute,
	})
	require.NoError(t, err)
	assigned, err := st.ScheduleOnce()
	require.NoError(t, err)
	require.Len(t, assigned, 1)

	code := 137
	resp := post(t, ts, "wtok", "/v1/jobs/"+job.ID+"/status", server.StatusRequest{
		WorkerID: assigned[0].WorkerID, State: model.JobKilled, ExitCode: &code,
		Reason: "max_runtime exceeded (30m0s)",
	})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	require.Equal(t, []notify.Event{{
		Kind: notify.KindWatchdogTrip, Job: job.ID, Device: "gpubox:gpu0",
		Reason: "max_runtime exceeded (30m0s)",
	}}, flush(t, n, sink))
}

// A "running" report is not terminal and must never be mistaken for one,
// whatever it carries.
func TestRunningReportEmitsNothing(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)

	resp := post(t, ts, "wtok", "/v1/jobs/"+job.ID+"/status", server.StatusRequest{
		WorkerID: job.WorkerID, State: model.JobRunning, Reason: "max_runtime exceeded (4h0m0s)",
	})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	require.Empty(t, flush(t, n, sink))
}

// A fault the store rejected changed nothing, so it must announce nothing.
func TestFaultOnUnknownDeviceEmitsNothing(t *testing.T) {
	ts, _, n, sink := newNotifyingServer(t)

	resp := post(t, ts, "wtok", "/v1/devices/nosuchbox:gpu9/fault",
		server.FaultRequest{Reason: "verify failed: 10-vram.sh: dirty"})
	require.Equal(t, http.StatusNotFound, resp.StatusCode)
	resp.Body.Close()

	require.Empty(t, flush(t, n, sink))
}

// No webhook configured is the default deployment: Config.Notifier is nil
// and every emit site must be a no-op rather than a panic.
func TestNoNotifierConfiguredIsSafe(t *testing.T) {
	ts, st, _, _ := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register",
		server.RegisterRequest{Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}}})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-a", LeaseTTL: time.Minute,
	})
	require.NoError(t, err)

	faultDevice(t, ts, "gpubox:gpu0", "verify failed: 10-vram.sh: dirty")

	code := 0
	sr := post(t, ts, "wtok", "/v1/jobs/"+job.ID+"/status", server.StatusRequest{
		WorkerID: job.WorkerID, State: model.JobKilled, ExitCode: &code,
		Reason: "max_runtime exceeded (4h0m0s)",
	})
	require.Equal(t, http.StatusOK, sr.StatusCode)
	sr.Body.Close()
}

package server_test

import (
	"net/http"
	"testing"
	"time"

	"github.com/mudler/resource-controller/internal/model"
	"github.com/mudler/resource-controller/internal/notify"
	"github.com/mudler/resource-controller/internal/server"
	"github.com/mudler/resource-controller/internal/store"
	"github.com/stretchr/testify/require"
)

// registerBody is what a worker posts at startup, with whatever it can prove
// about processes left over from an interrupted job.
func registerBody(proof model.RecoveryProof) server.RegisterRequest {
	return server.RegisterRequest{
		Host:     "gpubox",
		Devices:  []server.DeviceSpec{{Name: "gpu0"}},
		Recovery: proof,
	}
}

func stateOf(t *testing.T, st *store.Store, id string) model.DeviceState {
	t.Helper()
	devices, err := st.Devices()
	require.NoError(t, err)
	for _, d := range devices {
		if d.ID == id {
			return d.State
		}
	}
	t.Fatalf("device %s not found", id)
	return ""
}

// The containerised case, end to end over HTTP: a worker restarts while it
// has a job in flight — the pod was rescheduled, the image was rolled — and
// its device must come back to the pool on the worker's own credentials. No
// admin token appears in this test, and that is the point: today the only
// exit from this quarantine is POST /v1/devices/{id}/clear, which a worker
// cannot call.
func TestContainerisedWorkerRestartMidLeaseRecoversWithoutAnAdminToken(t *testing.T) {
	ts, st, _, c := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register", registerBody(model.RecoveryProof{}))
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./train"}, Submitter: "agent-a", LeaseTTL: time.Hour,
	})
	require.NoError(t, err)
	require.NoError(t, st.MarkRunning(job.ID, c.Now()))

	// The restarted process announces itself, proving its PID namespace went
	// with the container it died in.
	resp = post(t, ts, "wtok", "/v1/workers/register", registerBody(model.RecoveryProof{Isolated: true}))
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	// The stranded job is still reconciled as lost — recovery is about the
	// device, not about pretending the job survived.
	reloaded, err := st.Job(job.ID)
	require.NoError(t, err)
	require.Equal(t, model.JobLost, reloaded.State)

	require.Equal(t, model.DeviceReady, stateOf(t, st, "gpubox:gpu0"),
		"an isolated worker's device must return to the pool on registration alone")

	_, err = st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"./bench"}, Submitter: "agent-b", LeaseTTL: time.Hour,
	})
	require.NoError(t, err, "the recovered device must be genuinely schedulable")
}

// The dangerous case. A host worker restarting under systemd does NOT kill
// the jobs it started — they are reparented to init and may still be
// training on the card. A worker that cannot prove they are gone says
// nothing, and nothing is exactly what must happen to the device.
func TestHostWorkerThatCannotProveSurvivorsAreGoneDoesNotRecover(t *testing.T) {
	cases := []struct {
		name  string
		proof model.RecoveryProof
	}{
		{"no claim at all", model.RecoveryProof{}},
		{"looked and found a survivor", model.RecoveryProof{SurvivorsChecked: true, SurvivorsFound: true}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ts, st, _, c := newServer(t)

			resp := post(t, ts, "wtok", "/v1/workers/register", registerBody(model.RecoveryProof{}))
			require.Equal(t, http.StatusOK, resp.StatusCode)
			resp.Body.Close()

			job, err := st.Allocate(store.AllocateRequest{
				DeviceID: "gpubox:gpu0", Command: []string{"./train"}, Submitter: "agent-a", LeaseTTL: time.Hour,
			})
			require.NoError(t, err)
			require.NoError(t, st.MarkRunning(job.ID, c.Now()))

			resp = post(t, ts, "wtok", "/v1/workers/register", registerBody(tc.proof))
			require.Equal(t, http.StatusOK, resp.StatusCode)
			resp.Body.Close()

			require.Equal(t, model.DeviceUnhealthy, stateOf(t, st, "gpubox:gpu0"),
				"a device whose previous job may still be running on it must stay out of the pool")
		})
	}
}

// An operator must be able to answer "why is this device back?" without
// reading the controller's logs.
func TestAutoRecoveryEmitsAnEvent(t *testing.T) {
	ts, st, n, sink := newNotifyingServer(t)

	// Both devices go out the way idle devices actually go out: their worker
	// stopped reporting and the sweep quarantined them. No job is involved —
	// an unhealthyAfter of zero is how this test says "the silence has gone
	// on long enough" without needing the clock.
	res, err := st.Sweep(0, 0, time.Time{})
	require.NoError(t, err)
	require.Len(t, res.DevicesUnhealthy, 2)

	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:     "gpubox",
		Devices:  []server.DeviceSpec{{Name: "gpu0"}, {Name: "gpu1"}},
		Recovery: model.RecoveryProof{SurvivorsChecked: true},
	})
	require.Equal(t, http.StatusOK, resp.StatusCode)
	resp.Body.Close()

	var got []notify.Event
	for _, e := range flush(t, n, sink) {
		if e.Kind == notify.KindDeviceRecovered {
			got = append(got, e)
		}
	}
	require.Len(t, got, 2, "every device returned to the pool must be announced, by name")
	require.Equal(t, "gpubox:gpu0", got[0].Device)
	require.Contains(t, got[0].Reason, "worker_lost", "the event must say what the device was out for")
	require.Contains(t, got[0].Reason, "no surviving processes", "and what proof brought it back")
	require.Equal(t, "gpubox:gpu1", got[1].Device)
}

package server_test

import (
	"strings"
	"testing"
	"time"

	"github.com/mudler/resource-controller/internal/model"
	"github.com/mudler/resource-controller/internal/server"
	"github.com/mudler/resource-controller/internal/store"
	"github.com/stretchr/testify/require"
)

// ptr is a small helper so tests can build a *string inline — RegisterRequest
// and LabelsPushRequest's Sheet field is a pointer so nil (leave the stored
// sheet alone) can be told apart from an explicit, present "" (clear it).
func ptr(s string) *string { return &s }

// A registration carrying detected and declared labels stores each under
// the right provenance, and a host-wide fact (the "" key) reaches every
// device PRESENT in the map — gpu1 here has no facts of its own but is
// still explicitly reported (an empty submap), exactly what a real,
// non-failed gatherLabels pass sends for every configured device (see
// worker.labelsPayload): only a device a pass had a genuine failure for is
// ever left out of the map entirely.
func TestRegisterStoresDetectedAndDeclaredLabels(t *testing.T) {
	ts, st, _, _ := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:    "gpubox",
		Devices: []server.DeviceSpec{{Name: "gpu0"}, {Name: "gpu1"}},
		Labels: map[string]map[string]string{
			"":     {"rack": "a1"},
			"gpu0": {"vendor": "nvidia"},
			"gpu1": {},
		},
		DeclaredLabels: map[string]map[string]string{
			"gpu0": {"owner": "team-a"},
		},
	})
	defer resp.Body.Close()
	require.Equal(t, 200, resp.StatusCode)

	gpu0, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	byKey := map[string]model.Label{}
	for _, l := range gpu0 {
		byKey[l.Key+"/"+l.Source] = l
	}
	require.Equal(t, "nvidia", byKey["vendor/detected"].Value)
	require.Equal(t, "a1", byKey["rack/detected"].Value, "the host-wide fact must reach every device")
	require.Equal(t, "team-a", byKey["owner/declared"].Value)

	// gpu1 got no device-scoped facts of its own, but must still inherit the
	// host-wide one.
	gpu1, err := st.LabelsFor("gpubox:gpu1")
	require.NoError(t, err)
	require.Len(t, gpu1, 1)
	require.Equal(t, "rack", gpu1[0].Key)
	require.Equal(t, "a1", gpu1[0].Value)
	require.Equal(t, model.SourceDetected, gpu1[0].Source)
}

// The complement, and the fix-round-1 finding pinned directly at this
// layer: a device whose bare name is NOT a key in Labels at all — because
// its own probes failed this pass, per worker.labelsPayload — must be left
// completely untouched, host-wide fact included, not merely spared an
// empty-clear. A prior version of applyDeviceFacts iterated every device in
// deviceNames unconditionally once Labels was non-nil, which would have
// applied the host-wide fact alone to an omitted device and silently
// dropped whatever GPU/VRAM facts it had from an earlier pass.
func TestRegisterLeavesADeviceAbsentFromLabelsCompletelyUntouched(t *testing.T) {
	ts, st, _, _ := newServer(t)

	first := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:    "gpubox",
		Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels:  map[string]map[string]string{"gpu0": {"vram": "80G", "model": "a100"}},
	})
	first.Body.Close()
	require.Equal(t, 200, first.StatusCode)

	// gpu0's own probe failed this round (e.g. nvidia-smi broke): the
	// worker reports a host-wide fact but says nothing at all about gpu0.
	second := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:    "gpubox",
		Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels:  map[string]map[string]string{"": {"kernel": "6.8.0"}},
	})
	second.Body.Close()
	require.Equal(t, 200, second.StatusCode)

	labels, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	byKey := map[string]string{}
	for _, l := range labels {
		byKey[l.Key] = l.Value
	}
	require.Equal(t, "80G", byKey["vram"], "gpu0's stale facts must survive a round it was omitted from")
	require.Equal(t, "a100", byKey["model"])
	_, gotKernel := byKey["kernel"]
	require.False(t, gotKernel,
		"a device omitted from Labels must not even pick up the host-wide fact — it is untouched, not partially updated")
}

// A device-scoped value wins over a host-wide one on a key collision: the
// device fact is more specific and must not be shadowed.
func TestRegisterDeviceLabelWinsOverHostWideCollision(t *testing.T) {
	ts, st, _, _ := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:    "gpubox",
		Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels: map[string]map[string]string{
			"":     {"driver": "550.54"},
			"gpu0": {"driver": "560.10"},
		},
	})
	defer resp.Body.Close()
	require.Equal(t, 200, resp.StatusCode)

	labels, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Len(t, labels, 1)
	require.Equal(t, "560.10", labels[0].Value, "the device-scoped value must win the collision")
}

// A registration carrying a usage sheet stores both the host-wide sheet and
// a per-device one.
func TestRegisterStoresUsageSheets(t *testing.T) {
	ts, st, _, _ := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:         "gpubox",
		Devices:      []server.DeviceSpec{{Name: "gpu0"}},
		Sheet:        ptr("# gpubox\nshared rack A1"),
		DeviceSheets: map[string]string{"gpu0": "gpu0 runs the eval suite"},
	})
	defer resp.Body.Close()
	require.Equal(t, 200, resp.StatusCode)

	hostBody, _, err := st.HostDoc("gpubox", "")
	require.NoError(t, err)
	require.Equal(t, "# gpubox\nshared rack A1", hostBody)

	deviceBody, _, err := st.HostDoc("gpubox", "gpubox:gpu0")
	require.NoError(t, err)
	require.Equal(t, "gpu0 runs the eval suite", deviceBody)
}

// An oversized sheet (over 64KB) is rejected outright with 413, and nothing
// from that registration — sheet, labels, or the device/worker rows
// themselves — is stored: a hand-edited file must not be able to bloat the
// database, and a rejected request must not partially apply.
func TestRegisterRejectsOversizedSheet(t *testing.T) {
	ts, st, _, _ := newServer(t)

	huge := strings.Repeat("x", (64*1024)+1)
	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:    "gpubox",
		Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Sheet:   ptr(huge),
		Labels:  map[string]map[string]string{"gpu0": {"vendor": "nvidia"}},
	})
	defer resp.Body.Close()
	require.Equal(t, 413, resp.StatusCode)

	hostBody, at, err := st.HostDoc("gpubox", "")
	require.NoError(t, err)
	require.Empty(t, hostBody)
	require.True(t, at.IsZero())

	devices, err := st.Devices()
	require.NoError(t, err)
	require.Empty(t, devices, "the worker/device rows must not be created by a rejected registration")

	labels, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Empty(t, labels)
}

// An oversized PER-DEVICE sheet is rejected the same way as an oversized
// host sheet.
func TestRegisterRejectsOversizedDeviceSheet(t *testing.T) {
	ts, _, _, _ := newServer(t)

	huge := strings.Repeat("x", (64*1024)+1)
	resp := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host:         "gpubox",
		Devices:      []server.DeviceSpec{{Name: "gpu0"}},
		DeviceSheets: map[string]string{"gpu0": huge},
	})
	defer resp.Body.Close()
	require.Equal(t, 413, resp.StatusCode)
}

// A registration that explicitly reports an empty (but non-nil) label set
// for a device — a probe that ran fine and legitimately found nothing this
// round, e.g. a card was removed — clears whatever was previously detected
// for that device. This is the store's own documented replace semantics
// (see store.ReplaceLabels) applied faithfully at the HTTP layer: the
// controller cannot second-guess an explicit report.
func TestRegistrationWithExplicitEmptyLabelsClearsPreviouslyDetected(t *testing.T) {
	ts, st, _, _ := newServer(t)

	first := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels: map[string]map[string]string{"gpu0": {"vendor": "nvidia"}},
	})
	first.Body.Close()
	require.Equal(t, 200, first.StatusCode)

	before, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Len(t, before, 1, "sanity: the first registration actually stored the label")

	// The card was removed: the second registration explicitly says "gpu0
	// has zero detected labels now" rather than omitting the field.
	second := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels: map[string]map[string]string{"gpu0": {}},
	})
	second.Body.Close()
	require.Equal(t, 200, second.StatusCode)

	after, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Empty(t, after, "an explicit empty report must clear the previously detected set")
}

// The other half of the same contract, and the one the CARRIED-FORWARD
// review finding is actually about: a registration that omits the labels
// field entirely — Go's zero value, absent from the wire — must NOT be
// read as "detected nothing". The controller cannot tell that apart from a
// probe pass that failed outright, so it must do the only safe thing:
// leave whatever is already stored untouched. If this test is broken by
// changing handleRegister to unconditionally call ReplaceLabels with
// req.Labels (a nil map, which store.ReplaceLabels treats identically to an
// empty one — see TestReplaceLabelsWithEmptyMapClearsThatSource in
// internal/store), it must fail.
func TestRegistrationWithoutLabelsFieldPreservesPreviouslyDetected(t *testing.T) {
	ts, st, _, _ := newServer(t)

	first := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}},
		Labels: map[string]map[string]string{"gpu0": {"vendor": "nvidia"}},
	})
	first.Body.Close()
	require.Equal(t, 200, first.StatusCode)

	// A bare re-registration with no Labels field set at all — exactly what
	// a worker whose probe pass produced nothing sends (see
	// worker.labelsPayload).
	second := post(t, ts, "wtok", "/v1/workers/register", server.RegisterRequest{
		Host: "gpubox", Devices: []server.DeviceSpec{{Name: "gpu0"}},
	})
	second.Body.Close()
	require.Equal(t, 200, second.StatusCode)

	after, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Len(t, after, 1, "a registration silent about labels must never wipe what was already detected")
	require.Equal(t, "nvidia", after[0].Value)
}

// The dedicated periodic-push route stores labels and sheets the same way
// registration does, without requiring a full re-registration.
func TestPushLabelsStoresDetectedLabelsAndSheet(t *testing.T) {
	ts, st, _, _ := newServer(t)
	workerID := registerWorker(t, ts)

	resp := post(t, ts, "wtok", "/v1/workers/"+workerID+"/labels", server.LabelsPushRequest{
		Host:    "gpubox",
		Devices: []string{"gpu0"},
		Labels:  map[string]map[string]string{"gpu0": {"vendor": "nvidia"}},
		Sheet:   ptr("# gpubox"),
	})
	defer resp.Body.Close()
	require.Equal(t, 200, resp.StatusCode)

	labels, err := st.LabelsFor("gpubox:gpu0")
	require.NoError(t, err)
	require.Len(t, labels, 1)
	require.Equal(t, "nvidia", labels[0].Value)

	hostBody, _, err := st.HostDoc("gpubox", "")
	require.NoError(t, err)
	require.Equal(t, "# gpubox", hostBody)
}

// The whole reason handlePushLabels exists as a route separate from
// handleRegister: a live worker's periodic push must never be able to reap
// its own currently-running job. Calling /v1/workers/register again from a
// live process does exactly that (UpsertWorker's reapInFlightJobsLocked
// treats every re-registration as a fresh process with nothing running),
// so this pins that the labels-push route leaves an in-flight job and its
// device completely alone.
func TestPushLabelsDoesNotDisturbARunningJob(t *testing.T) {
	ts, st, _, c := newServer(t)
	workerID := registerWorker(t, ts)

	job, err := st.Allocate(store.AllocateRequest{
		DeviceID: "gpubox:gpu0", Command: []string{"sleep", "300"}, Submitter: "agent-a",
		LeaseTTL: 5 * time.Minute,
	})
	require.NoError(t, err)
	require.NoError(t, st.MarkRunning(job.ID, c.Now()))

	resp := post(t, ts, "wtok", "/v1/workers/"+workerID+"/labels", server.LabelsPushRequest{
		Host: "gpubox", Devices: []string{"gpu0"},
