	ts, _, _, _ := newServer(t)

	resp := post(t, ts, "wtok", "/v1/workers/register",
		server.RegisterRequest{Host: "gpubox", Devices: []server.DeviceSpec{
			{Name: "gpu0", MaxRuntimeSeconds: 3600},
