	require.NoError(t, st.UpsertHostDoc("gpubox", "gpubox:gpu0", "shared rack A1", future))

	resp := get(t, ts, "ctok", "/v1/devices/gpubox:gpu0/describe")
	defer resp.Body.Close()
	require.Equal(t, http.StatusOK, resp.StatusCode)

